// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // local ABI-identical mirrors of the calldata structs
    struct PayoffDefL { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct CurveL { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct InfoL {
        string name;
        string symbol;
        PayoffDefL payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        CurveL utilizationCurve;
    }

    interface IProductL {
        function initialize(InfoL calldata productInfo_) external;
    }

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 version) public {
        // the oracle the product is configured with must be a real contract that
        // reports `version`; the fuzzer picks the version the oracle exposes.
        MockOracle oracle = new MockOracle(version);

        InfoL memory info = InfoL({
            name: "T",
            symbol: "T",
            payoffDefinition: PayoffDefL(1, 0, bytes30(0)),
            oracle: address(oracle),
            maintenance: 1e18,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: type(uint256).max,
            utilizationCurve: CurveL(0, 0, 0, uint128(5e17))
        });

        // the test contract itself has code, so it passes the isContract controller check
        c.initialize(info);

        // RULE: after configuration, oracle() must expose the registered contract oracle,
        // so a call through it must succeed and report the oracle's own version.
        bool ok;
        try c.oracle().currentVersion() returns (uint256 v, uint256, int256) {
            ok = (v == version);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MockOracle {
    uint256 public version;
    constructor(uint256 v) { version = v; }
    function currentVersion() external view returns (uint256, uint256, int256) {
        return (version, block.timestamp, 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct PayoffDefinitionLocal {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }

    struct JumpRateUtilizationCurveLocal {
        int128 minRate;
        int128 maxRate;
        int128 targetRate;
        uint128 targetUtilization;
    }

    struct ProductInfoLocal {
        string name;
        string symbol;
        PayoffDefinitionLocal payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        JumpRateUtilizationCurveLocal utilizationCurve;
    }

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 feeRaw) public {
        // Fees must lie in the admissible domain: <= 1e18 (ONE)
        uint256 fee = bound(feeRaw, 0, 1e18);

        // Adversarial environment: a deployed oracle contract (an EOA would be
        // rejected by the contract's own isContract validation at initialization).
        OracleStub oracleStub = new OracleStub();

        PayoffDefinitionLocal memory payoff = PayoffDefinitionLocal({
            payoffType: 1, // non-linear type carrying 30 bytes of data
            payoffDirection: 0,
            data: bytes30(type(uint240).max)
        });

        ProductInfoLocal memory info = ProductInfoLocal({
            name: "P",
            symbol: "P",
            payoffDefinition: payoff,
            oracle: address(oracleStub),
            maintenance: fee,
            fundingFee: fee,
            makerFee: fee,
            takerFee: fee,
            positionFee: fee,
            makerLimit: fee,
            utilizationCurve: JumpRateUtilizationCurveLocal({
                minRate: 0,
                maxRate: 0,
                targetRate: 0,
                targetUtilization: 0
            })
        });

        // Initialize c with the fuzzed configuration (struct encodes identically
        // to the contract's ProductInfo calldata layout).
        (bool initOk, ) = address(c).call(
            abi.encodeWithSelector(c.initialize.selector, info)
        );
        require(initOk, "initialization reverted");

        // General rule: after a successful initialization with a contract oracle,
        // c.oracle() must report the registered non-zero oracle address for ANY
        // admissible configuration parameters.
        assertTrue(address(c.oracle()) != address(0));
    }
}

contract OracleStub {
    fallback() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Adversarial environment: the registered oracle must be a real contract.
        OracleStub stub = new OracleStub(seed);

        // Derive a spread of payoff-definition variants from the fuzzed seed.
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(uint8(seed % 4));
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(uint8((seed >> 8) % 4));

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "",
            symbol: "",
            payoffDefinition: PayoffDefinition({
                payoffType: pType,
                payoffDirection: pDir,
                data: bytes30(uint240(seed >> 16))
            }),
            oracle: IOracleProvider(address(stub)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Initialize; skip inputs the reference legitimately rejects (e.g. invalid payoff definition).
        bool initialized = true;
        try c.initialize(info) {
            initialized = true;
        } catch {
            return; // outside admissible domain
        }

        assertTrue(initialized && address(c.oracle()) == address(stub) && address(stub) != address(0));
    }
}

// Minimal live-oracle stand-in: a real contract so initialization passes its isContract check.
contract OracleStub {
    uint256 public v;
    constructor(uint256 s) { v = s; }
    function sync() external pure returns (uint256, uint256, int256) { return (0, 0, 0); }
    function currentVersion() external pure returns (uint256, uint256, int256) { return (0, 0, 0); }
    function atVersion(uint256) external pure returns (uint256, uint256, int256) { return (0, 0, 0); }
}

