pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // ABI-compatible local mirrors of the calldata structs C.initialize expects
    struct LocalPayoffDefinition {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }

    struct LocalProductInfo {
        string name;
        string symbol;
        LocalPayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        uint128[4] utilizationCurve; // minRate, maxRate, targetRate, targetUtilization (packed ints, ABI-compatible)
    }

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 oracleSeed) public {
        // Deploy a set of candidate oracle contracts; fuzzer picks among them.
        address[] memory oracles = new address[](3);
        oracles[0] = address(new DummyOracle());
        oracles[1] = address(new DummyOracle());
        oracles[2] = address(new DummyOracle());

        // Fuzzer selects the oracle registered at initialization (wide domain).
        address chosenOracle = oracles[oracleSeed % 3];
        vm.assume(chosenOracle != address(0));

        LocalProductInfo memory info;
        info.name = "P";
        info.symbol = "P";
        info.payoffDefinition = LocalPayoffDefinition({
            payoffType: 0,
            payoffDirection: 0,
            data: bytes30(0)
        });
        info.oracle = chosenOracle;
        info.maintenance = 1e18;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = type(uint256).max;
        info.utilizationCurve[0] = 0;
        info.utilizationCurve[1] = 0;
        info.utilizationCurve[2] = 0;
        info.utilizationCurve[3] = 0;

        // Initialize from a contract address (UControllerProvider requires isContract(msg.sender)).
        address fakeController = address(new DummyController());
        vm.prank(fakeController);
        c.initialize(info);

        // General rule: oracle() must expose exactly the oracle registered at initialization.
        assertTrue(
            address(c.oracle()) == chosenOracle,
            "oracle() must return the registered oracle address"
        );
    }
}

contract DummyOracle {
    // No functions needed: initialization only checks that the address has code.
}

contract DummyController {
    // No functions needed: initialize only stores the controller and checks isContract.
}

