pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OracleStub o;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint256 pt,
        uint256 maintenance,
        uint256 fundingFee,
        uint256 makerFee,
        uint256 takerFee,
        uint256 positionFee,
        uint256 makerLimit
    ) public {
        // keep params in the admissible domain (wide): fees are UFixed18 with scale 1e18, must be <= 1
        uint8 ptype = uint8(bound(pt, 1, 2));
        UFixed18 maint_ = UFixed18.wrap(bound(maintenance, 0, 5 ether));
        UFixed18 fund_ = UFixed18.wrap(bound(fundingFee, 0, 1 ether));
        UFixed18 mkFee_ = UFixed18.wrap(bound(makerFee, 0, 1 ether));
        UFixed18 tkFee_ = UFixed18.wrap(bound(takerFee, 0, 1 ether));
        UFixed18 posFee_ = UFixed18.wrap(bound(positionFee, 0, 1 ether));
        UFixed18 mkLimit_ = UFixed18.wrap(bound(makerLimit, 0, 5 ether));

        // adversarial-adjacent helper: a live oracle contract address (initialize requires code at oracle)
        o = new OracleStub();

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        PayoffDefinition memory pd;
        pd.payoffType = PayoffDefinitionLib.PayoffType(ptype);
        pd.payoffDirection = PayoffDefinitionLib.PayoffDirection(0);
        pd.data = bytes30(0);

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(o)),
            maintenance: maint_,
            fundingFee: fund_,
            makerFee: mkFee_,
            takerFee: tkFee_,
            positionFee: posFee_,
            makerLimit: mkLimit_,
            utilizationCurve: curve
        });

        // this test contract has code, so it satisfies the contract-controller check in initialize
        c.initialize(info);

        // GENERAL RULE: the product must expose exactly the oracle contract registered at initialization
        assertTrue(
            address(c.oracle()) == address(o) && address(o) != address(0),
            "oracle() must return the registered oracle address"
        );
    }
}

// minimal live oracle address (only needs code so Address.isContract passes)
contract OracleStub {
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    fallback() external {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // local ABI-layout mirrors (same layout, used only for encoding)
    struct PD { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct Curve { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct PI {
        string name;
        string symbol;
        PD payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        Curve utilizationCurve;
    }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, uint256 rawData) public {
        vm.assume(payoffType <= 4);
        vm.assume(payoffDirection <= 1);
        bytes30 data = bytes30(uint240(rawData));

        c = new C();
        Oracle oracle = new Oracle();
        Initializer ini = new Initializer();

        PI memory info;
        info.name = "P";
        info.symbol = "P";
        info.payoffDefinition = PD(payoffType, payoffDirection, data);
        info.oracle = address(oracle);
        info.maintenance = 1e18;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = 100e18;
        info.utilizationCurve = Curve(1e17, 2e18, 5e17, 8e17);

        bytes4 sel = bytes4(keccak256(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"
        ));
        bytes memory payload = abi.encodeWithSelector(sel, info);

        // initialize must be called from a contract (controller check uses msg.sender's code)
        (bool okInit, ) = address(ini).call(abi.encodeWithSignature("init(address,bytes)", address(c), payload));
        vm.assume(okInit);

        // General rule: payoffDefinition() returns the stored definition verbatim
        assertTrue(
            uint8(c.payoffDefinition().payoffType) == payoffType &&
            uint8(c.payoffDefinition().payoffDirection) == payoffDirection &&
            c.payoffDefinition().data == data,
            "payoffDefinition must return the stored value"
        );
    }
}

contract Oracle {
    // only needs code so Address.isContract passes during initialize
}

contract Initializer {
    function init(address target, bytes memory payload) external {
        (bool ok, ) = target.call(payload);
        require(ok, "init failed");
    }
}
